+
+async function drainAndStop(hal: HalServer): Promise<void> {
+  const openSockets = [...hal.wss.clients].filter(socket => socket.readyState !== WebSocket.CLOSED);
+  await Promise.all(
+    openSockets.map(socket => new Promise<void>(resolve => void socket.once('close', () => resolve())))
+  );
+  await hal.stop();
 }

